CREATE OR REPLACE FUNCTION private.tri_towers_board_finish_v2(b jsonb, reason text, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE time_i integer:=0; stock_i integer:=0; total_i integer; result jsonb;
BEGIN
 IF reason IN ('cleared','take_score') THEN time_i:=greatest(0,((b->>'deadline')::bigint-at_ms)/1000)*(b#>>'{rules,timePerSecond}')::integer;END IF;
 IF reason='cleared' THEN stock_i:=(52-(b->>'cursor')::integer)*(b#>>'{rules,stockPerCard}')::integer;END IF;
 total_i:=(b->>'score')::integer+time_i+stock_i;
 result:=jsonb_build_object('score',total_i,'scoreBefore',(b->>'scoreBefore')::integer,
  'stageScore',total_i-(b->>'scoreBefore')::integer,'timeBonus',time_i,'stockBonus',stock_i,'reason',reason,'completedAt',at_ms);
 RETURN b||jsonb_build_object('score',total_i,'result',result,'phase','stage_complete','deadline',at_ms+(b#>>'{rules,holdMs}')::bigint,
  'event',jsonb_build_object('label',CASE reason WHEN 'cleared' THEN 'All Three Towers Cleared!' WHEN 'take_score' THEN 'Score taken' WHEN 'ready_timeout' THEN 'Round not started' WHEN 'timeout' THEN 'Time expired' ELSE 'Round complete' END,'points',time_i+stock_i));
END $function$

CREATE OR REPLACE FUNCTION private.boxdrop_board_finish(b jsonb, reason text, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE remaining bigint:=greatest(0,least(100000,(b->>'deadline')::bigint-at_ms)); partial_i bigint:=0;
 speed_i bigint:=0; recycling_i bigint:=0; before_i bigint:=(b->>'scoreBefore')::bigint; display_i bigint:=(b->>'score')::bigint; total_i bigint;
BEGIN
 IF b->>'phase'<>'playing' THEN RAISE EXCEPTION 'boxdrop:phase';END IF;
 IF reason NOT IN ('take_score','timeout','full_clear','scales_unavailable') THEN RAISE EXCEPTION 'boxdrop:finish_reason';END IF;
 IF reason<>'timeout' THEN
  SELECT coalesce(sum((s->>'sum')::bigint*20),0) INTO partial_i FROM jsonb_array_elements(b->'scales') s WHERE s->>'status'='active';
  IF (b->>'completedFirstOrders')::integer>0 THEN speed_i:=100*(remaining/500);recycling_i:=(b->>'recycleIndicator')::integer;END IF;
 END IF;
 total_i:=display_i+partial_i+speed_i+recycling_i;
 RETURN b||jsonb_build_object('phase','stage_complete','deadline',at_ms+9000,'score',total_i,
  'result',jsonb_build_object('reason',reason,'scoreBefore',before_i,'displayScore',display_i,'score',total_i,'stageScore',total_i-before_i,
   'firstOrderPoints',b->'firstOrderPoints','closurePoints',b->'closurePoints','partialPoints',(b->>'partialPoints')::bigint+partial_i,
   'speedBonus',speed_i,'recyclingBonus',recycling_i,'bonusEligible',(b->>'completedFirstOrders')::integer>0,
   'completedFirstOrders',b->'completedFirstOrders','remainingMs',CASE WHEN reason='timeout' THEN 0 ELSE remaining END,'completedAt',at_ms),
  'event',jsonb_build_object('label',CASE WHEN reason='full_clear' THEN 'All orders complete!' WHEN reason='timeout' THEN 'Time up' ELSE 'Round complete' END,'points',partial_i+speed_i+recycling_i));
END $function$

CREATE OR REPLACE FUNCTION private.boxdrop_board_reduce(b jsonb, action text, items integer[], at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE scale_i integer; s jsonb; q jsonb; current_i jsonb; sum_i integer; count_i integer; points_i integer:=0; closures_i integer; label_i text;
BEGIN
 IF b->'rules' IS DISTINCT FROM private.boxdrop_rules() THEN RAISE EXCEPTION 'boxdrop:rules_version';END IF;
 IF b->>'phase'='intro' THEN
  IF at_ms<(b->>'deadline')::bigint THEN IF action='tick' THEN RETURN b;END IF;RAISE EXCEPTION 'boxdrop:phase';END IF;
  b:=b||jsonb_build_object('phase','playing','startedAt',b->'deadline','deadline',(b->>'deadline')::bigint+100000,'event',jsonb_build_object('label','Place a box','points',0));
 END IF;
 IF b->>'phase'<>'playing' THEN RAISE EXCEPTION 'boxdrop:phase';END IF;
 -- Timeout has priority over every otherwise legal command.
 IF at_ms>=(b->>'deadline')::bigint THEN RETURN private.boxdrop_board_finish(b,'timeout',(b->>'deadline')::bigint);END IF;
 IF action='tick' THEN RETURN b;END IF;
 IF action='take_score' THEN RETURN private.boxdrop_board_finish(b,'take_score',at_ms);END IF;
 current_i:=b->'current';
 IF action='recycle' THEN
  IF cardinality(items) IS DISTINCT FROM 1 OR items[1] IS DISTINCT FROM (current_i->>'id')::integer THEN RAISE EXCEPTION 'boxdrop:illegal_move';END IF;
  q:=b->'queue';current_i:=current_i||'{"recycled":true}'::jsonb;
  IF jsonb_array_length(q)<6 THEN b:=private.boxdrop_fresh(b||jsonb_build_object('queue',q||jsonb_build_array(current_i)));
  ELSE b:=b||jsonb_build_object('current',q->0,'queue',(q-0)||jsonb_build_array(current_i));END IF;
  RETURN b||jsonb_build_object('recycleIndicator',1000*(6-jsonb_array_length(b->'queue')),'recycleStreak',(b->>'recycleStreak')::integer+1,'event',jsonb_build_object('label','Recycled','points',0));
 END IF;
 IF action IS DISTINCT FROM 'place' OR cardinality(items) IS DISTINCT FROM 2 OR items[1] NOT BETWEEN 0 AND 3 OR items[1] IS NULL OR items[2] IS DISTINCT FROM (current_i->>'id')::integer THEN RAISE EXCEPTION 'boxdrop:illegal_move';END IF;
 scale_i:=items[1];s:=b->'scales'->scale_i;
 IF s->>'status'<>'active' THEN RAISE EXCEPTION 'boxdrop:illegal_move';END IF;
 s:=s||jsonb_build_object('boxes',(s->'boxes')||jsonb_build_array(current_i),'sum',(s->>'sum')::integer+(current_i->>'value')::integer);
 sum_i:=(s->>'sum')::integer;count_i:=jsonb_array_length(s->'boxes');
 IF sum_i=(s->>'target')::integer THEN
  IF s->>'stage'='1' THEN
   points_i:=3200;label_i:='32 order complete';
   s:=s||'{"stage":2,"target":21,"limit":3,"sum":0,"boxes":[]}'::jsonb;
   b:=b||jsonb_build_object('completedFirstOrders',(b->>'completedFirstOrders')::integer+1,'firstOrderPoints',(b->>'firstOrderPoints')::integer+points_i);
  ELSE
   closures_i:=(b->>'closures')::integer+1;points_i:=(ARRAY[5000,10000,15000,25000])[closures_i];label_i:='Scale closed';
   s:=s||'{"status":"closed"}'::jsonb;
   b:=b||jsonb_build_object('closures',closures_i,'closurePoints',(b->>'closurePoints')::integer+points_i);
  END IF;
 ELSIF sum_i>(s->>'target')::integer THEN s:=s||'{"status":"broken"}'::jsonb;label_i:='Scale overloaded';
 ELSIF count_i=(s->>'limit')::integer THEN
  points_i:=20*sum_i;s:=s||'{"status":"short"}'::jsonb;label_i:='Full scale · partial score';
  b:=b||jsonb_build_object('partialPoints',(b->>'partialPoints')::integer+points_i);
 ELSE label_i:='Box placed';END IF;
 b:=jsonb_set(b,ARRAY['scales',scale_i::text],s)||jsonb_build_object('score',(b->>'score')::bigint+points_i,'recycleStreak',0,
  'event',jsonb_build_object('label',label_i,'points',points_i,'scale',scale_i,'box',current_i));
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'scales') x WHERE x->>'status'='active') THEN
  RETURN private.boxdrop_board_finish(b,CASE WHEN (b->>'closures')::integer=4 THEN 'full_clear' ELSE 'scales_unavailable' END,at_ms);
 END IF;
 RETURN private.boxdrop_fresh(b);
END $function$

CREATE OR REPLACE FUNCTION private.boxdrop_random(bound integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE bytes bytea; n bigint;
BEGIN
 IF bound<1 THEN RAISE EXCEPTION 'boxdrop:random_bound';END IF;
 LOOP
  bytes:=extensions.gen_random_bytes(4);
  n:=get_byte(bytes,0)::bigint*16777216+get_byte(bytes,1)::bigint*65536+get_byte(bytes,2)::bigint*256+get_byte(bytes,3);
  EXIT WHEN n<4294967296-(4294967296%bound);
 END LOOP;
 RETURN (n%bound)::integer;
END $function$

CREATE OR REPLACE FUNCTION private.tri_towers_board_deal(b jsonb, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 b:=private.tri_towers_board_deal_v2(b,at_ms);
 IF b#>>'{rules,version}' IN ('tri-towers/3','tri-towers/4','tri-towers/5') THEN b:=b||jsonb_build_object('phase','intro','deadline',at_ms+(b#>>'{rules,roundIntroMs}')::bigint);END IF;
 RETURN b;
END $function$

CREATE OR REPLACE FUNCTION private.tri_towers_board_reduce_v2(b jsonb, action text, idx integer, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE phase text:=b->>'phase'; run_i integer; points integer; before_i integer; cursor_i integer:=(b->>'cursor')::integer;
BEGIN
 IF phase NOT IN ('ready','playing') THEN RAISE EXCEPTION 'tri_towers:phase';END IF;
 IF at_ms>=(b->>'deadline')::bigint THEN RETURN private.tri_towers_board_finish_v2(b,CASE WHEN phase='ready' THEN 'ready_timeout' ELSE 'timeout' END,at_ms);END IF;
 IF action='tick' THEN RETURN b;END IF;
 -- Validate BEFORE admitting the playing clock. Invalid actions cannot start it.
 IF action='remove' THEN
  IF private.tri_towers_legal(b,idx) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tri_towers:illegal_move';END IF;
 ELSIF action='draw' THEN
  IF cursor_i>=52 THEN RAISE EXCEPTION 'tri_towers:stock_empty';END IF;
 ELSIF action<>'take_score' OR phase<>'playing' THEN RAISE EXCEPTION 'tri_towers:invalid_action';END IF;
 IF phase='ready' THEN b:=b||jsonb_build_object('phase','playing','deadline',at_ms+(b#>>'{rules,stageMs}')::bigint);END IF;
 IF action='take_score' THEN RETURN private.tri_towers_board_finish_v2(b,'take_score',at_ms);END IF;
 IF action='remove' THEN
  run_i:=(b->>'run')::integer+1;
  points:=(b->'rules'->'streakAwards'->>least(run_i-1,jsonb_array_length(b#>'{rules,streakAwards}')-1))::integer;
  b:=b||jsonb_build_object('removed',(b->'removed')||to_jsonb(idx),'waste',b->'deck'->idx);
  IF idx<3 THEN points:=points+(b->'rules'->'peakBonuses'->>((SELECT count(*) FROM jsonb_array_elements_text(b->'removed') r WHERE r::integer<3)-1)::integer)::integer;END IF;
  b:=b||jsonb_build_object('run',run_i,'score',(b->>'score')::integer+points,'event',jsonb_build_object('label',CASE WHEN idx<3 THEN 'Tower cleared' ELSE 'Streak '||run_i END,'points',points));
 ELSE
  before_i:=(b->>'score')::integer;points:=greatest(0,before_i-(b#>>'{rules,drawPenalty}')::integer)-before_i;
  b:=b||jsonb_build_object('cursor',cursor_i+1,'waste',b->'deck'->cursor_i,'run',0,'score',before_i+points,'event',jsonb_build_object('label','Stock drawn','points',points));
 END IF;
 IF jsonb_array_length(b->'removed')=28 THEN RETURN private.tri_towers_board_finish_v2(b,'cleared',at_ms);END IF;
 IF b#>>'{rules,version}'<>'tri-towers/5' AND (b->>'cursor')::integer=52 AND NOT EXISTS(SELECT 1 FROM generate_series(0,27) i WHERE private.tri_towers_legal(b,i)) THEN
  RETURN private.tri_towers_board_finish_v2(b,'exhausted',at_ms);
 END IF;
 RETURN b;
END $function$

CREATE OR REPLACE FUNCTION private.tri_towers_board_reduce(b jsonb, action text, idx integer, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF b#>>'{rules,version}' IN ('tri-towers/3','tri-towers/4','tri-towers/5') AND b->>'phase'='intro' THEN
  IF at_ms<(b->>'deadline')::bigint THEN
   IF action='tick' THEN RETURN b;END IF;
   RAISE EXCEPTION 'tri_towers:round_intro';
  END IF;
  b:=b||jsonb_build_object('phase','ready','deadline',(b->>'deadline')::bigint+(b#>>'{rules,readyMs}')::bigint);
 END IF;
 b:=private.tri_towers_board_reduce_v2(b,action,idx,at_ms);
 IF b#>>'{rules,version}' IN ('tri-towers/4','tri-towers/5') AND b->>'phase'='stage_complete' AND b#>>'{result,reason}'='cleared' THEN
  -- Absolute result identity/time, never additive: replay cannot extend the hold.
  b:=jsonb_set(b,'{deadline}',to_jsonb((b#>>'{result,completedAt}')::bigint+(b#>>'{rules,holdMs}')::bigint+(b#>>'{rules,clearCelebrationMs}')::bigint));
 END IF;
 RETURN b;
END $function$
